        self.assertFalse(packet["chart_summary"]["has_drawable_data"])
        self.assertTrue(packet["chart_summary"]["is_exact_next_session_packet"])
        self.assertIn("精确次日操作图谱 packet 未提供 chart_render_model", " ".join(chart["warnings"]))

