    def test_bootstrap_provider_model_acceptance_dry_run_blocks_missing_credentials(self):
        self._with_meta_store()
        self._with_bootstrap_env(
            COMMAND_CENTER_BOOTSTRAP_MODE="live_light",
            COMMAND_CENTER_LIVE_TUSHARE_ON_OPEN="true",
            COMMAND_CENTER_LIVE_DEEPSEEK_ON_OPEN="true",
            COMMAND_CENTER_LIVE_BOOTSTRAP_SYMBOL_LIMIT="2",
        )

        response = self.client.post(
            "/api/bootstrap/provider-model-acceptance-dry-run",
            json={
                "source": "unit_test_missing_credentials",
                "approved_by_user": True,
                "symbols": ["000001.SZ"],
                "include_tushare": True,
                "include_deepseek": True,
                "apis": ["trade_cal", "daily"],
            },
        ).json()

        self.assertTrue(response["ok"])
        task = response["data"]["task"]
        self.assertEqual(task["status"], "success")
        self.assertEqual(
            task["current_step"],
            "provider_model_acceptance_dry_run_blocked_missing_credentials_no_external_call",
        )
        payload = task["payload_safe"]
        credential_rows = {row["provider"]: row for row in payload["credential_presence_rows"]}
        self.assertEqual(credential_rows["tushare"]["status"], "missing_no_value_read")
        self.assertEqual(credential_rows["deepseek"]["status"], "missing_no_value_read")
        self.assertFalse(credential_rows["tushare"]["present"])
        self.assertFalse(credential_rows["deepseek"]["present"])
        self.assertFalse(credential_rows["tushare"]["values_read"])
        self.assertFalse(credential_rows["deepseek"]["values_exposed"])
        scope_ticket = payload["acceptance_scope_ticket"]
        self.assertEqual(scope_ticket["scope_hash_algorithm"], "sha256")
        self.assertEqual(len(scope_ticket["scope_hash"]), 64)
        self.assertEqual(scope_ticket["scope_hash_input"]["credential_presence_status"], "required_env_key_missing_no_values_read")
        self.assertFalse(scope_ticket["credential_values_included"])
        self.assertFalse(scope_ticket["env_key_names_included"])
        summary = payload["acceptance_dry_run_summary"]
        self.assertEqual(summary["status"], "acceptance_dry_run_blocked_missing_credentials")
        self.assertEqual(summary["acceptance_scope_hash"], scope_ticket["scope_hash"])
        self.assertEqual(
            summary["real_acceptance_preflight_receipt_status"],
            "real_acceptance_preflight_blocked_dry_run_not_ready",
        )
        self.assertFalse(summary["real_acceptance_preflight_ready_to_execute"])
        self.assertEqual(summary["credential_presence_status"], "required_env_key_missing_no_values_read")
        self.assertEqual(summary["credential_required_provider_count"], 2)
        self.assertEqual(summary["credential_present_provider_count"], 0)
        self.assertEqual(summary["credential_missing_provider_count"], 2)
        self.assertTrue(summary["blocked_by_missing_credentials"])
        self.assertFalse(summary["ready_for_user_approved_real_acceptance"])
        self.assertEqual(summary["allowed_next_step"], "configure_server_credentials_then_rerun_dry_run")
        self.assertFalse(summary["real_acceptance_task_implemented"])
        self.assertIn("server credential presence for selected providers", summary["missing_evidence_items"])
        self.assertIn("skip credential presence gate", summary["not_allowed_next_steps"])
        self.assertIn("promote dry-run to provider-backed acceptance", summary["not_allowed_next_steps"])
        rows = {row["phase_key"]: row for row in payload["acceptance_dry_run_rows"]}
        self.assertEqual(rows["server_secret_preflight"]["status"], "dry_run_secret_presence_missing_no_values_exposed")
        self.assertFalse(rows["server_secret_preflight"]["passed"])
        self.assertEqual(rows["server_secret_preflight"]["credential_presence_summary"]["missing_provider_count"], 2)
        real_preflight = payload["real_acceptance_preflight_receipt"]
        self.assertEqual(real_preflight["status"], "real_acceptance_preflight_blocked_dry_run_not_ready")
        self.assertFalse(real_preflight["dry_run_ready_for_user_approved_real_acceptance"])
        self.assertFalse(real_preflight["ready_to_execute_real_task"])
        real_preflight_rows = {row["criterion"]: row for row in payload["real_acceptance_preflight_rows"]}
        self.assertEqual(
            real_preflight_rows["credential_presence_ready_without_value_exposure"]["status"],
            "blocked_missing_server_credentials",
        )
        self.assertTrue(real_preflight_rows["credential_presence_ready_without_value_exposure"]["blocks_real_execution"])
        self.assertEqual(
            task["call_ledger"][0]["call_status"],
            "local_acceptance_dry_run_blocked_missing_credentials_no_external_call",
        )
        self.assertEqual(task["call_ledger"][0]["request_params_safe"]["credential_missing_provider_count"], 2)
        self.assertFalse(task["call_ledger"][0]["external_calls_triggered"])
        self.assertFalse(task["call_ledger"][0]["tushare_called"])
        self.assertFalse(task["call_ledger"][0]["deepseek_called"])
        self.assertFalse(task["external_calls_triggered"])
        self.assertFalse(task["tushare_called"])
        self.assertFalse(task["deepseek_called"])
        self.assertTrue(task["does_not_execute_trades"])
        self.assertTrue(task["does_not_modify_strategy_action"])

    def test_health_and_cache_endpoints(self):
        self._with_meta_store()
        self._with_parquet_root()
        health = self.client.get("/health").json()
        self.assertTrue(health["ok"])
        self.assertFalse(health["data"]["external_calls_on_startup"])
        self.assertFalse(health["data"]["deepseek_called"])
        self.assertFalse(health["data"]["tushare_called"])
        self.assertEqual(health["call_ledger"][0]["api"], "local_health_check")
        self.assertFalse(health["call_ledger"][0]["external"])
        self.assertIn("GET /health", health["warnings"][0])
        model_strategy = health["data"]["deepseek_model_strategy"]
        model_purposes = set(model_strategy) - {"source", "contains_secret"}
        self.assertEqual(
            model_purposes,
            {"default", "explain", "projection", "factor_explain", "fast", "healthcheck", "feeder"},
        )
        self.assertEqual(model_strategy["default"], model_strategy["explain"])
        self.assertEqual(model_strategy["projection"], model_strategy["explain"])
        self.assertEqual(model_strategy["factor_explain"], model_strategy["explain"])
        self.assertEqual(model_strategy["healthcheck"], model_strategy["fast"])
        self.assertEqual(model_strategy["feeder"], model_strategy["fast"])
        self.assertFalse(model_strategy["contains_secret"])
        self.assertNotIn("token", json.dumps(model_strategy, ensure_ascii=False).lower())
        self.assertNotIn("api_key", json.dumps(model_strategy, ensure_ascii=False).lower())

        bootstrap = self.client.get("/api/bootstrap/status").json()
        self.assertTrue(bootstrap["ok"])
        self.assertEqual(bootstrap["data"]["schema_version"], "command_center_bootstrap_runtime_mode.v1")
        self.assertEqual(bootstrap["data"]["mode"], "cache_only")
        self.assertEqual(bootstrap["data"]["status"], "cache_only_ready_no_bootstrap")
        self.assertTrue(bootstrap["data"]["cache_only"])
        self.assertTrue(bootstrap["data"]["read_only"])
        self.assertFalse(bootstrap["data"]["external_calls_triggered"])
        self.assertFalse(bootstrap["data"]["tushare_called"])
        self.assertFalse(bootstrap["data"]["deepseek_called"])
        self.assertFalse(bootstrap["data"]["github_called"])
        self.assertTrue(bootstrap["data"]["policy"]["cache_api_external_calls"] is False)
        self.assertTrue(bootstrap["data"]["policy"]["post_task_required_for_external_calls"])
        self.assertTrue(bootstrap["data"]["policy"]["live_light_requires_opt_in"])
        self.assertTrue(bootstrap["data"]["policy"]["live_light_task_implemented"])
        self.assertFalse(bootstrap["data"]["policy"]["live_light_provider_execution_implemented"])
        self.assertTrue(bootstrap["data"]["policy"]["provider_linkage_rows_visible"])
        self.assertTrue(bootstrap["data"]["policy"]["live_light_activation_receipt_visible"])
        self.assertTrue(bootstrap["data"]["policy"]["live_light_provider_model_acceptance_runbook_visible"])
        self.assertFalse(bootstrap["data"]["policy"]["production_live_light_complete"])
        self.assertFalse(bootstrap["data"]["policy"]["live_full_enabled"])
        self.assertFalse(bootstrap["data"]["live_light"]["enabled"])
        self.assertTrue(bootstrap["data"]["live_light"]["bootstrap_task_implemented"])
        self.assertFalse(bootstrap["data"]["live_light"]["provider_execution_implemented"])
        self.assertTrue(bootstrap["data"]["live_light"]["activation_receipt_visible"])
        self.assertTrue(bootstrap["data"]["live_light"]["provider_model_acceptance_runbook_visible"])
        self.assertTrue(bootstrap["data"]["live_light"]["ready_for_provider_execution_design"])
        self.assertTrue(bootstrap["data"]["live_light"]["ready_for_acceptance_design"])
        self.assertFalse(bootstrap["data"]["live_light"]["ready_for_user_approved_acceptance_task"])
        self.assertFalse(bootstrap["data"]["live_light"]["ready_for_provider_execution"])
        self.assertFalse(bootstrap["data"]["live_light"]["ready_for_model_execution"])
